CREATE TABLE "MAPPING"."REMAP_RUNS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SCOPE_KIND" VARCHAR(16) NOT NULL CHECK ("SCOPE_KIND" IN ('ALL','BATCH','DATE_RANGE','ISSUE')),
    "SCOPE_VALUE" JSONB NOT NULL CHECK (jsonb_typeof("SCOPE_VALUE")='object'),
    "CONFIG_ID" BIGINT NOT NULL REFERENCES "MAPPING"."CONFIGS" ("ID"),
    "STATE" VARCHAR(16) NOT NULL DEFAULT 'RUNNING' CHECK ("STATE" IN ('RUNNING','PAUSED','DONE')),
    "CURSOR_EXTRACTION_ID" BIGINT NOT NULL DEFAULT 0 CHECK ("CURSOR_EXTRACTION_ID">=0),
    "UPPER_EXTRACTION_ID" BIGINT NOT NULL CHECK ("UPPER_EXTRACTION_ID">=0),
    "SELECTED" BIGINT NOT NULL DEFAULT 0 CHECK ("SELECTED">=0),
    "QUEUED" BIGINT NOT NULL DEFAULT 0 CHECK ("QUEUED">=0),
    "SKIPPED" BIGINT NOT NULL DEFAULT 0 CHECK ("SKIPPED">=0),
    "CREATED_BY" VARCHAR(128) NOT NULL,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPDATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "FINISHED_AT" TIMESTAMPTZ,
    CONSTRAINT "CK_REMAP_COUNTS" CHECK ("SELECTED"="QUEUED"+"SKIPPED"),
    CONSTRAINT "CK_REMAP_CURSOR" CHECK ("CURSOR_EXTRACTION_ID"<="UPPER_EXTRACTION_ID"),
    CONSTRAINT "CK_REMAP_FINISHED" CHECK (("STATE"='DONE')=("FINISHED_AT" IS NOT NULL))
);
CREATE INDEX "IX_REMAP_RUNNING" ON "MAPPING"."REMAP_RUNS" ("ID") WHERE "STATE"='RUNNING';

ALTER TABLE "MAPPING"."JOBS"
    ADD "PRIORITY" SMALLINT NOT NULL DEFAULT 0 CHECK ("PRIORITY">=0),
    ADD "REMAP_RUN_ID" BIGINT REFERENCES "MAPPING"."REMAP_RUNS" ("ID");
DROP INDEX "MAPPING"."IX_MAPPING_READY";
CREATE INDEX "IX_MAPPING_READY" ON "MAPPING"."JOBS" ("PRIORITY","NEXT_ATTEMPT_AT","ID") WHERE "STATUS"='PENDING';
CREATE INDEX "IX_MAPPING_REMAP_RUN" ON "MAPPING"."JOBS" ("REMAP_RUN_ID","STATUS") WHERE "REMAP_RUN_ID" IS NOT NULL;

COMMENT ON TABLE "MAPPING"."REMAP_RUNS" IS 'Lượt chạy lại mapping theo phạm vi và cấu hình được chốt khi tạo.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."ID" IS 'Khóa chính của lượt chạy lại.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."SCOPE_KIND" IS 'Phạm vi toàn bộ, đợt nhập, khoảng ngày hoặc mã vấn đề.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."SCOPE_VALUE" IS 'Tham số phạm vi đã kiểm tra hợp lệ.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."CONFIG_ID" IS 'Cấu hình hiện hành tại thời điểm tạo lượt chạy.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."STATE" IS 'Trạng thái đang xếp hàng, tạm dừng hoặc đã xếp hết phạm vi.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."CURSOR_EXTRACTION_ID" IS 'Extraction cuối đã xét trong giao dịch đã commit.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."UPPER_EXTRACTION_ID" IS 'Cận extraction ban đầu, không mở rộng trong lượt chạy.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."SELECTED" IS 'Số extraction đã xét trong các lô đã commit.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."QUEUED" IS 'Số job mới đã xếp trong lượt chạy.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."SKIPPED" IS 'Số extraction đã có job cùng cấu hình và engine.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."CREATED_BY" IS 'Tài khoản quản trị tạo lượt chạy.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."CREATED_AT" IS 'Thời điểm tạo lượt chạy.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."UPDATED_AT" IS 'Thời điểm cập nhật tiến độ hoặc trạng thái gần nhất.';
COMMENT ON COLUMN "MAPPING"."REMAP_RUNS"."FINISHED_AT" IS 'Thời điểm xếp hết phạm vi; job có thể vẫn đang xử lý.';
COMMENT ON COLUMN "MAPPING"."JOBS"."PRIORITY" IS 'Số nhỏ được lấy trước; CV mới mặc định bằng không, chạy lại lớn hơn không.';
COMMENT ON COLUMN "MAPPING"."JOBS"."REMAP_RUN_ID" IS 'Lượt chạy lại tạo job; để trống với scan thông thường.';
